const e={title:"TripReel - Bezplatná Aplikácia pre Animáciu Cestovania: Premeňte Fotografie na Krásne Videá",description:"Vytvorte úžasné cestovné videá s animovanými mapami a trasami letov. Bezplatná aplikácia pre animáciu cestovania s 3D mapovaním trás glóbusu. Automaticky premeňte svoje fotografie na krásne cestovné videá. Súkromie na prvom mieste, funguje offline.",keywords:"aplikácia pre animáciu cestovania, aplikácia pre animáciu mapy cestovania, aplikácia pre animáciu trasy cestovania, aplikácia pre animáciu letu, tvorca cestovných videí, automatické cestovné video, animovaná mapa cestovania, animácia trasy letu, animácia cestovania, animácia glóbusu, video rekapitulácie cestovania, fotografia na video, zvýraznenia cestovania, bezplatná aplikácia pre cestovanie, tvorca videa offline, súkromná aplikácia pre cestovanie, video z rolky kamery"},a={logoAlt:"TripReel Logo",appName:"TripReel",howItWorks:"Jak to funguje",video:"Video",features:"Funkcie",theApp:"Aplikácia"},o={badge:"Premeňte fotky na cestovné príbehy",title1:"Vaša galéria,",title2:"naplno využitá",description:"TripReel automaticky vytvára krásne cestovné videá z polohy vašich fotiek. Sledujte, ako vaše cesty ožívajú s úžasnými animovanými trasami a leteckými cestami na 3D glóbuse, zatiaľ čo vaše údaje zostávajú súkromné a bezpečné.",secure:"100% zabezpečené",worksOffline:"Funguje offline",globeAlt:"Animácia glóbusu TripReel"},i={title:"Ako to funguje",subtitle:"Tri jednoduché kroky k vytvoreniu dokonalého cestovného videa",step1:{title:"Povoliť prístup k fotkám",description:"Udeľte TripReel prístup k vašej galérii fotiek. Aplikácia číta iba metadáta o polohe, nič viac."},step2:{title:"Automatické rozpoznanie ciest",description:"TripReel analyzuje metadáta o polohe a inteligentne nájde vaše cesty na základe dátumov a miest."},step3:{title:"Vygenerujte video",description:"Sledujte, ako sa vaša cesta odvíja na krásnej animácii glóbusu, pripravená na zdieľanie na sociálnych sieťach."}},t={title:"Pozrite sa na kúzlo v akcii",subtitle:"Zistite, ako TripReel premení vašu galériu fotiek na úžasné cestovné videá",caption:"Takto môže vyzerať vaše finálne cestovné video"},n={title:"Všetko, čo potrebujete",subtitle:"Výkonné funkcie navrhnuté pre moderných cestovateľov",twoTap:{title:"Cestovné videá na dve kliknutia",description:"Vytvorte úžasné cestovné videá z vašej galérie fotiek len dvoma kliknutiami. Žiadne úpravy nie sú potrebné."},smartTrip:{title:"Chytré rozpoznanie ciest",description:"Automaticky nájde a zoskupí vaše cesty analýzou dátumov a metadát o polohe z vašich fotiek."},globe:{title:"Krásna animácia glóbusu",description:"Sledujte, ako vaša cesta ožíva na úžasnom 3D glóbuse zobrazujúcom vaše animované cestovné trasy a letecké cesty po celom svete."},privacy:{title:"Súkromie na prvom mieste",description:"Všetko sa spracováva na vašom zariadení. Vaše fotky nikdy neopustia váš telefón. Funguje v lietacom režime."},customStyles:{title:"Vlastné štýly",description:"Vyberte si z viacerých štýlov glóbusu a prispôsobení, aby zodpovedali vašej estetike a urobili každé video jedinečným."},manualControl:{title:"Manuálne ovládanie",description:"Môžete ručne pridať úplne nové cesty, ak neboli na vašom zariadení povolené lokalizačné služby."}},s={title:"Kreatívne nápady na videá",subtitle:"Nechajte sa inšpirovať tým, čo môžete vytvoriť s TripReel. Od rýchlych víkendových výletov po ročné dobrodružstvá, vytvárajte úžasné cestovné videá pre každú cestu.",description:"Či už vytvárate animáciu cestovnej mapy, dokumentujete leteckú trasu alebo tvoríte ročnú rekapituláciu ciest, TripReel vám jednoducho premení spomienky na videá na zdieľanie.",ideas:{yearRecap:{title:"Cestovanie v roku 2025",description:"Vytvorte automaticky video rekapituláciu vášho cestovania za rok 2025"},europeRoadTrip:{title:"Roadtrip po Európe",description:"Ukážte svoje európske dobrodružstvo s animovanými mapami trás"},southeastAsia:{title:"Cesta juhovýchodnou Áziou",description:"Vizualizujte svoju cestu s batohem naprieč viacerými krajinami"},japanRail:{title:"Vlakom po Japonsku",description:"Vytvorte mapové videá vašich vlakových ciest po Japonsku"},crossCountry:{title:"Naprieč USA",description:"Premeňte svoj americký roadtrip na epické video trasy"},islandHopping:{title:"Skákanie po ostrovoch",description:"Ukážte svoje cestovanie z ostrova na ostrov s úžasnými 3D animáciami"},worldTour:{title:"Zostrih svetového turné",description:"Viac ciest v jednom úžasnom globálnom video príbehu"},travelPlans:{title:"Cestovné plány na rok 2026",description:"Vizualizujte a naplánujte svoje vzrušujúce dobrodružstvá na rok 2026"},lifetimeTravel:{title:"Príbeh cestovania života",description:"Vytvorte video zachytávajúce všetky vaše celoživotné cesty"},regionalExplorer:{title:"Prieskumník regiónov",description:"Zmapujte svoje dobrodružstvá po krajoch, provinciách a regiónoch"},festivalCircuit:{title:"Festivalový okruh",description:"Zmapujte svoju cestu po hudobných festivaloch a akciách"},bikeRoutes:{title:"Moje výlety do miest",description:"Ukážte všetky svoje mestské únikové cesty"}}},r={title:"Aplikácia",subtitle:"Už k dispozícii v App Store",alt1:"Automatické cestovné videá - Vytvorte úžasné videá počas pár sekúnd",alt2:"Detekcia polohy fotiek - Využíva metadáta vašich fotiek",alt3:"Detekcia ciest - Automaticky zoskupuje vaše cesty",alt4:"Krásne videá glóbusu - Animácia glóbusu vašej cesty",alt5:"Vlastné štýly - Personalizujte svoje cestovné videá"},v={comingSoon:"Už čoskoro",androidTitle:"Android aplikácia už čoskoro!",androidMessage:'Verzia pre Android zatiaľ nie je k dispozícii, ale bude čoskoro. Napíšte mi na <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> a dám vám vedieť, až bude pripravená!',gotIt:"Jasné!"},p={title:"Často kladené otázky",subtitle:"Všetko, čo potrebujete vedieť o TripReel",q1:{question:"Môžem aplikáciu skutočne používať plne v lietacom režime?",answer:"Áno! Pre prémiových používateľov možno aplikáciu používať kompletne offline v lietacom režime bez akýchkoľvek obmedzení. Pre neprémiových používateľov sú niektoré funkcie podporované reklamami, ktoré môžu vyžadovať dočasné zapnutie internetu, ale prémiových používateľov žiadne reklamy nečakajú a aplikáciu možno plne používať v lietacom režime."},q2:{question:"Upgradoval som na Premium, ako môžem odstrániť vodoznak?",answer:"Mnoho ľudí sa pýta, aká aplikácia bola použitá na vytvorenie týchto videí, preto po upgrade na premium máte možnosť pridať menšiu verziu vodoznaku (iba s názvom aplikácie) alebo ho úplne odstrániť, ak chcete."},q3:{question:"Sú moje údaje z fotiek bezpečné a súkromné?",answer:"Absolútne! TripReel číta iba metadáta o polohe z vašich fotiek - nikdy nepristupujeme k obsahu samotných fotiek, neukladáme ho ani neprenášame. Všetko spracovanie prebieha lokálne na vašom zariadení a žiadne údaje nikdy neopustia váš telefón. Môžete si to overiť používaním aplikácie v lietacom režime - funguje dokonale offline!"},q4:{question:"Čo ak moje fotky nemajú údaje o polohe?",answer:"Žiadny problém! Ak neboli povolené lokalizačné služby, keď ste fotky porizovali, môžete ručne vytvoriť cesty a pridať polohy sami. Aplikácia vám dáva plnú kontrolu na prispôsobenie vašej cestovnej časovej osi."},q5:{question:"Ako aplikácia automaticky rozpoznáva moje cesty?",answer:"TripReel analyzuje metadáta o polohe a časové pečiatky z vašich fotiek, aby inteligentne identifikoval, kedy a kam ste cestovali. Zoskupuje blízke polohy a dátumy dohromady, aby automaticky rozpoznal vaše cesty bez akejkoľvek manuálnej práce."},q6:{question:"Môžem prispôsobiť vzhľad svojich videí?",answer:"Áno! Môžete si vybrať z viacerých štýlov glóbusu a prispôsobiť rôzne aspekty vašich animovaných cestovných videí, aby zodpovedali vašej osobnej estetike. Prémiový používatelia získajú prístup k ďalším štýlom animácie trás, motívom máp a možnostiam leteckých ciest."},q7:{question:"Potrebujem si vytvoriť účet?",answer:"Žiadny účet nie je potrebný! TripReel funguje okamžite po stiahnutí. Nie je potrebná žiadna registrácia, žiadne prihlásenie a nie sú potrebné žiadne osobné údaje. Jednoducho si stiahnite aplikáciu a začnite vytvárať svoje cestovné videá hneď."},q8:{question:"Prečo v mojej ceste chýba nejaká poloha?",answer:"Aplikácia môže pracovať iba s dostupnými údajmi, takže predovšetkým potrebujete mať v danej polohe aspoň pár fotiek. Zadruhé sa musíte uistiť, že ste mali povolené údaje o polohe, keď ste tam boli. Zatretie niekedy slabý GPS signál môže spôsobiť chybné údaje o polohe. Ak ste to všetko vylúčili a vaša poloha sa stále nezobrazuje, môžete ju ručne pridať z Prehľad ciest > tlačidlo Upraviť. Prosím tiež použite Kontakt na nahlásenie problému."},q9:{question:"Kam môžem zdieľať svoje úžasné video?",answer:"Samozrejme ho môžete zdieľať aj na všetkých sociálnych platformách. Pre lepšie prispôsobenie platforme aplikácia umožňuje rôzne pomery strán pre vaše videá."},q10:{question:"Kde môžem nahlásiť chybu?",answer:"Jednoducho ma kontaktujte priamo na marian@qod.ee a stručne vysvetlite, o aký problém sa jedná."}},l={title:"Emailová podpora",description:"Ak máte akúkoľvek spätnú väzbu alebo narazíte na akékoľvek problémy, neváhajte ma kontaktovať priamo na tento email a osobne prečítam a vyriešim váš požiadavok čo najrýchlejšie. Ďakujem, že používate aplikáciu!",close:"Zavrieť"},c={default:{title:"🍪 Cookies",message:"Na webe TripReel používame cookies na zlepšenie vášho zážitku. Nie sú zhromažďované žiadne osobné údaje.",accept:"Prijať",decline:"Odmietnuť",details:"Podrobnosti"},theme:{title:"🍪 Cookies",message:"🌙 Na uloženie vašej preferencie motívu musíte prijať základné cookies na webe TripReel. Bez nich nemožno vašu voľbu motívu uložiť.",accept:"Prijať",decline:"Odmietnuť",details:"Podrobnosti"}},m={privacy:"Zásady ochrany súkromia aplikácie",cookies:"Zásady cookies webu",contact:"Kontakt",cookiePreferences:"Predvoľby cookies",madeWith:"Vytvorené s",forTravelers:"pre cestovateľov po celom svete",copyright:"© {{year}} TripReel."},u={title:"Pripravení zdieľať svoju cestu?",description:"Stiahnite si TripReel ešte dnes a premeňte svoju galériu v krásne cestovné videá s animovanými mapami a trasami. Vaše dobrodružstvá si zaslúžia byť oslavené.",features:"Zadarmo na stiahnutie • Rýchle a pohodlné • Zaručené súkromie"},d={meta:e,header:a,hero:o,howItWorks:i,videoSection:t,features:n,videoIdeas:s,screenshots:r,appStore:v,faq:p,contact:l,cookieBanner:c,footer:m,cta:u};export{v as appStore,l as contact,c as cookieBanner,u as cta,d as default,p as faq,n as features,m as footer,a as header,o as hero,i as howItWorks,e as meta,r as screenshots,s as videoIdeas,t as videoSection};
